const cfg = process.env.PINPOINT_MESSAGING_RUNTIME ? JSON.parse(process.env.PINPOINT_MESSAGING_RUNTIME) : null;
const run = cfg ? describe : describe.skip, originalFetch = globalThis.fetch, tag = `contained-imports-${randomUUID()}`, password = `Fixture-${randomUUID()}aA1!`;
