  const f=await staged([{}]),file=await assetFile(f.id),before=await rowList(f.id),originalAdmin=state.admin!;let release!:()=>void,mark!:()=>void;const gate=new Promise<void>(resolve=>{release=()=>resolve();}),downloaded=new Promise<void>(resolve=>{mark=()=>resolve();});let timer:ReturnType<typeof setTimeout>|undefined,pending:Promise<Response>|undefined;
  state.admin=new Proxy(admin,{get(target,key){if(key==='storage')return new Proxy(target.storage,{get(storage,entry){if(entry==='from')return(bucket:string)=>{const client=storage.from(bucket);return new Proxy(client,{get(object,method){if(method==='download')return async(name:string,options?:Parameters<typeof object.download>[1])=>{const result=await object.download(name,options);mark();await gate;return result;};const value=Reflect.get(object,method);return typeof value==='function'?value.bind(object):value;}});};const value=Reflect.get(storage,entry);return typeof value==='function'?value.bind(storage):value;}});const value=Reflect.get(target,key);return typeof value==='function'?value.bind(target):value;}});
  try{as(0);pending=assetPost(req('POST',file),context(f.id));await Promise.race([downloaded,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('Actual Storage download did not reach the controlled gate')),20000);})]);sql(`update public.listing_import_jobs set stage='complete' where id='${f.id}'`);release();expect((await pending).status).toBe(409);expect(await assetList(f.id)).toHaveLength(0);expect(await rowList(f.id)).toEqual(before);expect((await stored(f.id)).stage).toBe('complete');}finally{if(timer)clearTimeout(timer);release();state.admin=originalAdmin;await pending?.catch(()=>undefined);}
