 async function consentToFinalDraft(jobId:string){
  const row=(await rowList(jobId))[0]!;expect(row.resulting_listing_id).toBeTruthy();
  const before=await actors[0]!.from('listings').select('*').eq('id',row.resulting_listing_id).single();expect(before.error).toBeNull();
  const result=await saveFinalDraft(before.data!,{...before.data!.metadata,publicContact:{email:accounts[0]!.email},contactConsent:true});
  const images=await admin.from('listing_images').select('id',{count:'exact'}).eq('listing_id',row.resulting_listing_id);expect(images.error).toBeNull();expect(images.count).toBe(3);
  const {evaluatePublishReadiness}=await import('@/features/listings/publish-validation');expect(evaluatePublishReadiness(result,images.count??0)).toMatchObject({ready:true,fieldErrors:[],imageError:null});return result;
 }
 async function saveFinalDraft(listing:Record<string,unknown>,metadata:unknown){
  as(0);const form=new FormData();for(const [key,value]of Object.entries(listing))if(value!==null&&['string','number','boolean'].includes(typeof value))form.set(key,String(value));form.set('expectedUpdatedAt',String(listing.updated_at));form.set('metadata',JSON.stringify(metadata));const saved=await updateListing(String(listing.id),form);expect(saved.success).toBe(true);if(!saved.success)throw Error('Actual listing save refused the fixture: '+saved.error);const actual=await actors[0]!.from('listings').select('*').eq('id',String(listing.id)).single();expect(actual.error).toBeNull();return actual.data!;
 }
