 const ownerControlFacts:Array<{name:string;data:Record<string,unknown>}>=[];
 async function ownerControlFact(name:string,data:Record<string,unknown>){ownerControlFacts.push({name,data});const fs=await import('node:fs');fs.writeFileSync(cfg.sourceRoot+'/artifacts/user-flow-property-owner-controls-native-observations.json',JSON.stringify({scope:'Owned clone only; explicit owner/application/transaction fixtures and actual commands. No renter-document or hosted/device acceptance.',facts:ownerControlFacts},null,2));}
 async function ownerControlListing(type:'rent'|'sale'='rent',status:'draft'|'published'='draft'){
  const id=randomUUID(),result=await admin.from('listings').insert({id,landlord_id:accounts[0]!.id,organization_id:orgA,title:'Declared owner control '+id,address:'Declared owner control address '+id,price:type==='sale'?1500000:8800,...(type==='sale'?{sale_price:1500000}:{}),listing_type:type,status,metadata:{responsibleAgentId:accounts[0]!.id,contactConsent:true,publicContact:{email:accounts[0]!.email}}}).select('*').single();expect(result.error).toBeNull();if(status==="published"){const visible=await actors[3]!.from("listings").select("id").eq("id",id).single();expect(visible.error).toBeNull();}return result.data!;
 }
 async function ownerControlStored(id:string){const result=await admin.from('listings').select('*').eq('id',id).maybeSingle();expect(result.error).toBeNull();return result.data;}
 async function ownerControlSession(index:number){const claims=await actors[index]!.auth.getClaims();expect(claims.error).toBeNull();expect(claims.data?.claims.sub).toBe(accounts[index]!.id);const session=claims.data?.claims.session_id;if(typeof session!=="string")throw Error("Actual session identity missing");assert.match(session,/^[a-f0-9-]{36}$/i);return session;}
 async function ownerControlHolder(statement:string){
  assert.match(cfg.dbName,/^pinpoint-release-[0-9a-f-]{36}-db$/);sql('select 1');
  const {spawn}=await import('node:child_process');
  const child=spawn('docker',['exec','-i','-e',`PGPASSWORD=${cfg.dbPassword}`,cfg.dbName,'psql','-h','127.0.0.1','-U','supabase_admin','-d','postgres','--no-psqlrc','--set','ON_ERROR_STOP=1','--quiet','--tuples-only','--no-align'],{stdio:['pipe','pipe','pipe'],windowsHide:true});
  let output='',errors='',pid=0;let timer:ReturnType<typeof setTimeout>|undefined;
  const exit=new Promise<number|null>((resolve,reject)=>{child.once('exit',resolve);child.once('error',()=>reject(Error('Owned transaction process could not start')));});void exit.catch(()=>undefined);
  const ready=new Promise<void>((resolve,reject)=>{timer=setTimeout(()=>reject(Error('Owned transaction readiness timed out')),30000);child.stdout.on('data',chunk=>{output=(output+String(chunk)).slice(-4000);const match=/OWNER_CONTROL_HELD:(\d+)/.exec(output);if(match){pid=Number(match[1]);clearTimeout(timer);resolve();}});child.stderr.on('data',chunk=>{errors=(errors+String(chunk)).replaceAll(String(cfg.dbPassword),'[withheld]').slice(-2000);});child.once('error',()=>reject(Error('Owned transaction process could not start')));child.once('exit',code=>{if(!pid)reject(Error('Owned transaction stopped: '+code+' '+errors));});});void ready.catch(()=>undefined);
  child.stdin.write("begin; "+statement+"; select 'OWNER_CONTROL_HELD:'||pg_backend_pid();\n");
  try{await ready;}catch(error){clearTimeout(timer);child.stdin.end('rollback;\n');await exit.catch(()=>undefined);throw error;}
  let finished=false;
  return{pid,async finish(commit:boolean){if(finished)return;finished=true;child.stdin.end(commit?'commit;\n':'rollback;\n');expect(await exit).toBe(0);}};
 }
 async function ownerControlBlockedBy(pid:number){assert.ok(Number.isSafeInteger(pid)&&pid>0);await expect.poll(()=>Number(sql(`select count(*) from pg_stat_activity where wait_event_type='Lock' and ${pid}=any(pg_blocking_pids(pid))`)),{timeout:20000,interval:200}).toBeGreaterThan(0);}

